from collections import namedtuple, defaultdict
trans = {'A': 0, 'B': 1, 'C': 2, 'D': 3}
trans_r = {0: 'A', 1: 'B', 2: 'C', 3: 'D'}

def translate(c, r):
	return (int(trans[c]), int(r) - 1)
Piece = namedtuple('Piece', ['side', 'type', 'pos'])
Pos = namedtuple('Position', ['c', 'r'])
pieces = {p: {t: {s: Piece(s, t, p) for s in 'WB'} for t in 'RBQNP'} for p in (Pos(c, r) for c in range(4) for r in range(4))}

def move_paths(c, r):
	orthogonals = (tuple(((c, r_) for r_ in range(r + 1, 4))), tuple(((c, r_) for r_ in reversed(range(r)))), tuple(((c_, r) for c_ in range(c + 1, 4))), tuple(((c_, r) for c_ in reversed(range(c)))))
	diagonals = (tuple(zip(range(c + 1, 4), range(r + 1, 4))), tuple(zip(range(c + 1, 4), reversed(range(r)))), tuple(zip(reversed(range(c)), range(r + 1, 4))), tuple(zip(reversed(range(c)), reversed(range(r)))))
	knights = [(c + 2, r + 1), (c + 2, r - 1), (c - 2, r + 1), (c - 2, r - 1), (c + 1, r + 2), (c - 1, r + 2), (c + 1, r - 2), (c - 1, r - 2)]
	knights = [((c, r),) for (c, r) in knights if 0 <= c < 4 and 0 <= r < 4]
	return {'R': orthogonals, 'B': diagonals, 'Q': orthogonals + diagonals, 'N': knights}
all_move_paths = {(c, r): move_paths(c, r) for c in range(4) for r in range(4)}
promotion_types = 'BNR'
pawn_capture_moves = defaultdict(tuple)
for (c_from, c_to) in ((0, (1,)), (1, (0, 2)), (2, (1, 3)), (3, (2,))):
	for r in range(2):
		pawn_capture_moves[pieces[c_from, r]['P']['W']] = tuple((pieces[to, r + 1]['P']['W'] for to in c_to))
		pawn_capture_moves[pieces[c_from, 3 - r]['P']['B']] = tuple((pieces[to, 2 - r]['P']['B'] for to in c_to))
	pawn_capture_moves[pieces[c_from, 2]['P']['W']] = tuple((pieces[to, 3][typ]['W'] for to in c_to for typ in promotion_types))
	pawn_capture_moves[pieces[c_from, 1]['P']['B']] = tuple((pieces[to, 0][typ]['B'] for to in c_to for typ in promotion_types))
pawn_advance_moves = defaultdict(tuple)
for c in range(4):
	for r in range(2):
		pawn_advance_moves[pieces[c, r]['P']['W']] = (pieces[c, r + 1]['P']['W'],)
		pawn_advance_moves[pieces[c, 3 - r]['P']['B']] = (pieces[c, 2 - r]['P']['B'],)
	pawn_advance_moves[pieces[c, 2]['P']['W']] = tuple((pieces[c, 3][typ]['W'] for typ in promotion_types))
	pawn_advance_moves[pieces[c, 1]['P']['B']] = tuple((pieces[c, 0][typ]['B'] for typ in promotion_types))

def rank(piece):
	if piece.side == 'W':
		return piece.pos[1] + 1
	else:
		return 4 - piece.pos[1]

def win_with_move(grid, pos_from, piece, turn, m):
	grid_ = grid.copy()
	grid_[piece.pos] = piece
	del grid_[pos_from]
	return not forced_win(grid_, 'B' if turn == 'W' else 'W', m - 1)

def forced_win(grid, turn, m):
	for piece in (p for p in grid.values() if p.side == turn):
		if piece.type == 'P':
			if m > 1:
				for new_piece in pawn_advance_moves[piece]:
					if new_piece.pos not in grid and win_with_move(grid, piece.pos, new_piece, turn, m):
						return True
			for new_piece in pawn_capture_moves[piece]:
				other_p = grid.get(new_piece.pos, None)
				if other_p and other_p.side != turn:
					if other_p.type == 'Q':
						return True
					elif m > 1 and win_with_move(grid, piece.pos, new_piece, turn, m):
						return True
			continue
		for path in all_move_paths[piece.pos][piece.type]:
			for pos in path:
				other_p = grid.get(pos, None)
				if other_p and other_p.side == turn:
					break
				elif other_p and other_p.side != turn and (other_p.type == 'Q'):
					return True
				elif m > 1 and win_with_move(grid, piece.pos, Piece(piece.side, piece.type, pos), turn, m):
					return True
				if other_p:
					break
	return False
for _ in range(int(input().strip())):
	(w, b, m) = [int(x) for x in input().strip().split(' ')]
	white = [Piece('W', t, translate(c, r)) for (t, c, r) in (input().strip().split(' ') for _ in range(w))]
	black = [Piece('B', t, translate(c, r)) for (t, c, r) in (input().strip().split(' ') for _ in range(b))]
	grid = {p.pos: p for p in white + black}
	if m % 2 == 0:
		m -= 1
	print('YES' if forced_win(grid, 'W', m) else 'NO')
